/* ── 1. BG CANVAS — pixel squares ── */
(function(){
  const cv=document.getElementById('bg-canvas'), cx=cv.getContext('2d');
  let W,H;
  function resize(){ W=cv.width=window.innerWidth; H=cv.height=window.innerHeight; }
  resize(); window.addEventListener('resize',resize,{passive:true});
  class Node{
    constructor(){this.reset();}
    reset(){
      this.x=Math.random()*W; this.y=Math.random()*H;
      this.vx=(Math.random()-0.5)*0.25; this.vy=(Math.random()-0.5)*0.25;
      this.r=[2,2,3,4,4,6,8][Math.floor(Math.random()*7)];
      this.g=Math.random()>0.65; this.a=Math.random()*0.5+0.25; this.ph=Math.random()*Math.PI*2;
    }
    tick(){ this.x+=this.vx; this.y+=this.vy; if(this.x<-50||this.x>W+50||this.y<-50||this.y>H+50)this.reset(); }
    draw(t){
      const p=0.75+Math.sin(t*0.0008+this.ph)*0.25, al=this.a*p;
      if(this.g){
        const g=cx.createRadialGradient(this.x,this.y,0,this.x,this.y,this.r*5);
        g.addColorStop(0,`rgba(93,198,38,${al*0.3})`); g.addColorStop(1,'transparent');
        cx.beginPath(); cx.arc(this.x,this.y,this.r*5,0,Math.PI*2); cx.fillStyle=g; cx.fill();
      }
      cx.fillStyle=this.g?`rgba(93,198,38,${al})`:`rgba(50,80,140,${al*0.6})`;
      cx.fillRect(this.x-this.r,this.y-this.r,this.r*2,this.r*2);
    }
  }
  class Pulse{
    constructor(a,b){this.a=a;this.b=b;this.t=0;this.spd=0.003+Math.random()*0.004;this.sz=Math.random()*2+1;this.alive=true;}
    tick(){this.t+=this.spd;if(this.t>=1)this.alive=false;}
    draw(){
      const x=this.a.x+(this.b.x-this.a.x)*this.t, y=this.a.y+(this.b.y-this.a.y)*this.t;
      const tx=this.a.x+(this.b.x-this.a.x)*Math.max(0,this.t-0.18), ty=this.a.y+(this.b.y-this.a.y)*Math.max(0,this.t-0.18);
      const g=cx.createLinearGradient(tx,ty,x,y);
      g.addColorStop(0,'rgba(93,198,38,0)'); g.addColorStop(1,'rgba(93,198,38,0.85)');
      cx.beginPath(); cx.moveTo(tx,ty); cx.lineTo(x,y); cx.strokeStyle=g; cx.lineWidth=this.sz; cx.stroke();
      cx.fillStyle=`rgba(93,198,38,0.9)`;
      cx.fillRect(x-3,y-3,6,6);
    }
  }
  const COUNT=Math.min(Math.floor(window.innerWidth*window.innerHeight/6500),150);
  const nodes=Array.from({length:COUNT},()=>new Node());
  let pulses=[],lastPulse=0,edges=[];
  const DIST=190;
  function buildEdges(){
    edges=[];
    for(let i=0;i<nodes.length;i++) for(let j=i+1;j<nodes.length;j++){
      const dx=nodes[i].x-nodes[j].x,dy=nodes[i].y-nodes[j].y,d=Math.sqrt(dx*dx+dy*dy);
      if(d<DIST)edges.push({a:nodes[i],b:nodes[j],d});
    }
  }
  function loop(t){
    cx.clearRect(0,0,W,H);
    nodes.forEach(n=>n.tick());
    buildEdges();
    edges.forEach(({a,b,d})=>{
      cx.beginPath(); cx.moveTo(a.x,a.y); cx.lineTo(b.x,b.y);
      cx.strokeStyle=`rgba(20,60,140,${(1-d/DIST)*0.14})`; cx.lineWidth=0.6; cx.stroke();
    });
    nodes.forEach(n=>n.draw(t));
    if(t-lastPulse>260&&edges.length){
      lastPulse=t;
      const e=edges[Math.floor(Math.random()*edges.length)];
      pulses.push(new Pulse(e.a,e.b));
      if(Math.random()>0.55)pulses.push(new Pulse(e.b,e.a));
    }
    pulses=pulses.filter(p=>p.alive);
    pulses.forEach(p=>{p.tick();p.draw();});
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();

/* ── 2. NAVBAR ── */
const nav=document.getElementById('nav');
window.addEventListener('scroll',()=>nav.classList.toggle('scrolled',scrollY>50),{passive:true});

/* ── 3. SCROLL REVEAL ── */
function stagger(sel,delay){
  const els=document.querySelectorAll(sel);
  const obs=new IntersectionObserver((entries)=>{
    entries.forEach(e=>{
      if(!e.isIntersecting)return;
      const i=Array.from(els).indexOf(e.target);
      setTimeout(()=>e.target.classList.add('in'),i*delay);
      obs.unobserve(e.target);
    });
  },{threshold:0.1});
  els.forEach(el=>obs.observe(el));
}
stagger('.srv-card',90);
stagger('.t-step',70);
stagger('.niv-cell',65);
stagger('.pillar',55);
new IntersectionObserver((e)=>{if(e[0].isIntersecting)document.getElementById('dino-side').classList.add('in');},{threshold:0.15}).observe(document.getElementById('dino-side'));

/* ── 4. TIMELINE ── */
const tlP=document.getElementById('tl-progress');
const tlS=document.getElementById('timeline');
const dots=document.querySelectorAll('[data-dot]');
if(tlP){
  new IntersectionObserver((e)=>{
    if(e[0].isIntersecting){
      setTimeout(()=>{tlP.style.width='100%';},400);
      dots.forEach((d,i)=>setTimeout(()=>d.classList.add('lit'),400+i*280));
    }
  },{threshold:0.3}).observe(tlS);
}

/* ── 5. SVG DRAW ── */
(function(){
  function initDraw(){
    const paths=document.querySelectorAll('.dp');
    if(!paths.length)return;
    let totalDelay=0;
    paths.forEach(path=>{
      const len=path.getTotalLength();
      path.style.setProperty('--len',len);
      path.style.setProperty('--delay',totalDelay+'s');
      const dur=Math.max(0.25,len/2100);
      path.style.setProperty('--dur',dur+'s');
      totalDelay+=dur*0.72;
    });
    setTimeout(()=>paths.forEach(p=>p.classList.add('drawn')),900);
  }
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initDraw);}
  else{initDraw();}
})();

